-- Book of Magic: Techno-Wizard weapons and devices (printed 314-333)
-- 70 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~111-book-of-magic-techno-wizard-items.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('kizh-tw-sensor-gauntlet', 'Kizh TW Sensor Gauntlet', 'rifts', 'gear', NULL, 64000, '64,000-90,000 credits. Rare outside of Atlantis.', '2D6 S.D.C.', 0, NULL, '30 P.P.E. to activate; one hour per activation', NULL, NULL, NULL, NULL, 'A spined gauntlet the Kizh sell as a mystical tracking system; it is a general sensor, not a weapon, and its long spines are probes that fold back when idle. It gives the sensor features of a bionic sensor hand (heat, motion, radiation, radar detector) and a bionic molecular analyzer, plus Sense Evil, Sense Magic, Eyes of the Wolf and Locate at 8th level proficiency. The book points to World Book 21: Splynn Dimensional Market for it.', 'Rifts Book of Magic p.314', NULL),
  ('tw-mega-blade', 'Mega-Blade (TW)', 'rifts', 'weapon', NULL, NULL, '100 times the weapon''s normal cost for a standard Mega-Blade (active life of 3+1D4 years): a 300 credit sword costs 30,000. A 10 year life adds 100,000 credits, 20 years 180,000, 30 years 320,000, 50 years 700,000, 100 years 1.2 million, and another million per additional century up to 300 years. Custom Qua-Teek work is 50%-200% higher. One contained spell (wizard invocations of levels 1-5) adds 350,000-500,000 credits. Rare outside Splynn and other Splugorth markets.', 'By weapon type; the weapon''s S.D.C. damage becomes the same in M.D. (a 2D6+2 S.D.C. sword does 2D6+2 M.D.)', 1, 'Melee', NULL, NULL, NULL, NULL, 130, 'A Techno-Wizard attachment that turns an ordinary S.D.C. melee weapon into a Mega-Damage one for years; any ancient weapon type except a bow or sling can take it. The enchantment needs an 8th level Techno-Wizard or a Mystic Kuznya of any level. The weapon has 130 M.D.C. and is harmed only by attacks aimed at it. With the optional contained spell, it can be cast up to three times a day at 5th level strength, the user supplying the spell''s P.P.E. (or double that in I.S.P.).', 'Rifts Book of Magic p.314-315', NULL),
  ('tw-demon-claws', 'Demon Claws', 'rifts', 'weapon', NULL, 1000000, '1-2 million credits. Rare in most of North America; at least 1000 pairs went to the leaders of Tolkeen''s defense force.', '1D4 M.D. unenergized. Activated: the wearer''s P.S. becomes Supernatural P.S. (a character who already has it gains 1D6+8 P.S.), and the claws add 2D6 M.D. to a cut, rake or stab', 1, 'Melee', '25 P.P.E. or 50 I.S.P. to activate; 15 minutes', NULL, NULL, NULL, 400, 'A pair of armor-plated mechanical gauntlets with metal or bone talons and crystals set in the top or the knuckles. Activated, they parry Mega-Damage blades and other melee weapons unharmed, but cannot parry arrows, bullets or energy blasts (thrown objects at -3); holding an energy weapon does triple damage to the claws and 2D6 M.D. a melee round to the wearer. Bonuses: +1 to strike, +2 to parry, +2 to disarm, +2 to pull punch. Penalties: -2 to strike with a gun and -30% to skills needing manual dexterity. Both must be worn. 250 P.P.E. to create.', 'Rifts Book of Magic p.317-318', NULL),
  ('tw-earthshaker', 'Earthshaker', 'rifts', 'weapon', NULL, 150000, '150,000-200,000 credits. Fair to poor availability.', '1D4x10 M.D. plus knockdown penalties; struck on the ground, knockdown penalties only, in a ten foot (3 m) radius', 1, 'Melee', '35 P.P.E. or 70 I.S.P. to activate; one melee round (15 seconds) per level of the user', 'Each strike counts as one melee attack', NULL, NULL, NULL, 'A TW mace or hammer with a large quartz crystal at its head that looses a wave of force on each hit, like the Shockwave spell but confined to the one target. To create: 140 P.P.E., a metal or stone hammer or mace, the crystal, and the spells Shockwave (45) and Power Weapon (35); 6D6 hours.', 'Rifts Book of Magic p.318', NULL),
  ('tw-enforcer-gauntlet', 'Enforcer Gauntlet', 'rifts', 'weapon', NULL, 200000, '200,000-250,000 credits for the basic model; fair availability. Sold in pairs.', 'Punches do damage as a Supernatural P.S. equal to the wearer''s own P.S.', 1, 'Hand to hand combat only', '15 P.P.E. or 30 I.S.P. to recharge; two minutes per activation', NULL, NULL, NULL, NULL, 'Also called the Power Glove. A gauntlet with quartz crystals in the knuckles that lets the wearer punch as if supernaturally strong and parry M.D. melee weapons. It cannot be concealed, and gives -15% to skills needing manual dexterity and -1 to strike with firearms. To create: 50 P.P.E. (double in I.S.P.), a metal gauntlet, four quartz crystals, and the spells Fist of Fury (10) and Superhuman Strength (10); 4D6 hours.', 'Rifts Book of Magic p.318', NULL),
  ('tw-advanced-enforcer-gauntlet', 'Advanced Enforcer Gauntlet', 'rifts', 'weapon', NULL, 350000, '350,000-500,000 credits; poor availability. Sold in pairs.', 'Punches do damage as a Supernatural P.S. equal to the wearer''s own P.S. plus 2D6 M.D.; a crushing attack does 2D6 M.D. per squeeze', 1, 'Hand to hand combat only', '30 P.P.E. or 60 I.S.P. to recharge; two minutes per activation', NULL, NULL, NULL, NULL, 'The advanced Enforcer Gauntlet, built on the Combat Gauntlet from Juicer Uprising. Same penalties as the basic model: obvious, -15% to skills needing manual dexterity, -1 to strike with firearms. To create: 90 P.P.E. (double in I.S.P.), the Combat Gauntlet, four quartz crystals and a large one in the battery slot, and the spells Fist of Fury (10), Superhuman Strength (10), Energy Bolt (6) and Mystic Fulcrum (5); 6D6 hours.', 'Rifts Book of Magic p.318', NULL),
  ('nexus-knight-plasma-lance', 'Nexus Knight Plasma Lance', 'rifts', 'weapon', 10, 100000, '100,000+ credits. Rare even in England.', '4D6 M.D. per blast; 2D6 M.D. per hit as a blunt weapon in its fiery aura; 6D6 M.D. on a charging strike from horseback or a vehicle, which counts as three melee actions', 1, '1600 feet (488 m)', 'Two minutes. A Fire Bolt spell (7 P.P.E.), 8 P.P.E. or 15 I.S.P. buys five blasts or two minutes of energy aura', 'Up to five blasts per melee; each blast counts as one melee attack', NULL, NULL, NULL, 'A Techno-Wizard lance from Rifts World Book Three: England, favored by the Supreme Nexus Knights and copied by the few Techno-Wizards in Europe; it has not reached North America. Most common among Mrrlyn''s minions and the knights of Camelot. 140 P.P.E. to create.', 'Rifts Book of Magic p.318', NULL),
  ('nexus-knight-plasma-sword', 'Nexus Knight Plasma Sword', 'rifts', 'weapon', 7, 50000, '50,000-70,000 credits. Rare even in England.', '2D6 M.D. per fire ball, or 2D6 M.D. per strike as a magic flaming sword', 1, 'Fire ball: 1200 feet (366 m)', 'Until all six fire balls are launched or two minutes pass. A Fire Bolt spell (7 P.P.E.), 8 P.P.E. or 15 I.S.P. buys six blasts or two minutes as a flaming sword', 'Six per melee round; each blast counts as one melee attack', NULL, NULL, NULL, 'A sword-style copy of the Nexus Knight Plasma Lance, from Rifts World Book Three: England. Most common among Mrrlyn''s minions and the Knights of Camelot. 90 P.P.E. to create.', 'Rifts Book of Magic p.318', NULL),
  ('nexus-knight-electro-shield', 'Nexus Knight Electro-Shield', 'rifts', 'weapon', 7, 300000, '300,000-600,000 credits. Rare even in England.', '3D6 M.D. per lightning bolt', 1, '50 feet (15.2 m) per bolt (double at a ley line)', 'Five minutes per level of the user; each bolt fired shortens the duration by one minute. Activation: Call Lightning (15) and Energy Disruption (12) cast into the shield, or 27 P.P.E., or 40 I.S.P., for five minutes', 'Each bolt counts as one melee attack', NULL, NULL, NULL, 'A demon-faced shield with crystals set in its eyes, carried by Nexus Knight Commanders and Supreme Nexus Knights (Rifts World Book Three: England). It parries as a shield and fires lightning from the eyes. While it is active the user is impervious to energy and energy weapons, and magic energy does half damage.', 'Rifts Book of Magic p.318', NULL),
  ('nexus-knight-helm-of-all-seeing', 'Nexus Knight Helm of All Seeing', 'rifts', 'gear', NULL, 150000, '150,000-250,000 credits. Rare even in England.', NULL, 0, NULL, 'Five minutes per level of the user. Activation: Energize (12) and Fire Bolt (7) cast into the helm, or 12 P.P.E. or 24 I.S.P.', NULL, NULL, NULL, NULL, 'A helmet with a binocular-like pair of sockets where the eye slit would be (Rifts World Book Three: England). The wearer can See the Invisible, See Aura, see infrared light and strong heat like a thermo-imager, detect magic concealment and recognize illusions. Most common among Mrrlyn''s minions and the Knights of Camelot.', 'Rifts Book of Magic p.319', NULL),
  ('tw-flaming-dagger', 'TW Flaming Dagger', 'rifts', 'weapon', NULL, 40000, '40,000-50,000 credits. Reasonably common, good availability.', '2D6 M.D.', 1, 'Melee', '5 P.P.E. or 10 I.S.P. to activate; two minutes (8 melee rounds) per level of experience of the one who activates it', NULL, NULL, NULL, NULL, 'A bladeless knife hilt of wood or metal holding a single ruby and wires; activated, a blade of fire rises from the slot at its top. To create: 65 P.P.E. and the spell Fire Bolt (7) or Circle of Flame (10). New in this book.', 'Rifts Book of Magic p.319', NULL),
  ('tw-ice-blade', 'Ice Blade', 'rifts', 'weapon', NULL, 100000, '100,000 to 250,000 credits. Uncommon, poor availability.', '3D6 M.D. (double to beings vulnerable to magic, cold or ice), plus cold penalties: -1 on initiative, -1 to parry and dodge, -10% on speed for 1D4 melee rounds per successful strike', 1, 'Melee', '10 P.P.E. or 20 I.S.P. to activate; two minutes (8 melee rounds) per level of experience of the one who activates it', NULL, NULL, NULL, NULL, 'A sword of blown glass or shaped crystal, its hilt studded with 2-4 blue sapphires and one or two diamonds (2000 credits in all). Each strike frosts the area hit with a cold felt through M.D.C. body and power armor; the penalties do not stack, but their duration does. Parrying the blade causes neither cold nor damage. To create: Frostblade (15) and Ice (15) and 133 P.P.E. New in this book.', 'Rifts Book of Magic p.319', NULL),
  ('tw-knucklebusters', 'Knucklebusters', 'rifts', 'weapon', NULL, 250000, '250,000 credits for one, 450,000 for a pair. Fair to poor availability; 5,000 were distributed among Tolkeen fighters.', '1D6 M.D. per hit', 1, 'Melee', '12 P.P.E. or 24 I.S.P. to activate; five minutes (20 melees)', NULL, NULL, NULL, NULL, 'Small, concealable TW brass knuckles, or a studded plate fixed across the knuckles of a glove or gauntlet, that give an ordinary person a Mega-Damage punch; they do M.D. only on a punch. Wearing them gives -10% to skills needing manual dexterity and -1 to strike with a gun or bow. One or two can be used. 85 P.P.E. to create.', 'Rifts Book of Magic p.319', NULL),
  ('tw-lightning-axe', 'Lightning Axe', 'rifts', 'weapon', NULL, 65000, '65,000-95,000 credits. Poor to fair availability.', '2D6 M.D. as an axe or 2D6 M.D. per blast of electricity. Each surge sent while the axe is lodged in a machine with electronics does double damage, with a 01-45% chance of frying one electronic system', 1, 'Close combat, or 200 feet (61 m) when thrown', '12 P.P.E. or 21 I.S.P. to activate; one melee round (15 seconds) per level of experience of the one who activates it', 'Each chop and each electrical surge counts as one melee attack', NULL, NULL, NULL, 'A 3-4 foot (0.9 to 1.2 m) rod plated in gold or copper, ending in an axe blade and an insulated two-handed grip. Double surge damage applies to computers, sensors, radios, vehicles and robots, not body or power armor; the book gives a percentile table of the system fried (communications, sensors, optics, computers, locomotion, a secondary weapon, a main weapon, or a fire in the pilot compartment). +1 to strike in hand to hand and when thrown. To create: Call Lightning (15), Electric Arc (8) and 130 P.P.E. New in this book.', 'Rifts Book of Magic p.319-320', NULL),
  ('tw-lightning-mace-tw-1300', 'Lightning Mace TW-1300', 'rifts', 'weapon', NULL, 50000, '50,000-80,000 credits (typically the latter on the Black Market). Fair availability, good at Arzno. Silver spikes are 150 credits each at Arzno and the Colorado Baronies.', '4D6 M.D. activated (impact and electrical field together); an opponent takes 1D6 M.D. when the mace parries; electric blast 3D6 M.D. Unactivated: 2D4 S.D.C., or 4D4 Hit Points to vampires with silver spikes', 1, 'Melee; electric blast 100 feet (30.5 m)', '12 P.P.E. or 24 I.S.P. to activate; two melee rounds (30 seconds) per activation', 'Each strike or electric blast counts as one melee attack', NULL, NULL, NULL, 'A mace with an amethyst in its head and about four feet (1.2 m) of heavy copper wire threaded through holes in the striking surface. +1 to strike with the energy blast. To create: 80 P.P.E., a mace or M.D.C. alloy club, a small amethyst worth 60 credits, the wire, and the spells Call Lightning (15), Electric Arc (8) and Energy Field (10).', 'Rifts Book of Magic p.320', NULL),
  ('tw-lightning-rod', 'Lightning Rod', 'rifts', 'weapon', NULL, 55000, '55,000-85,000 credits. Reasonably common; fair to good availability.', '2D4 M.D. as a blunt weapon; 1D6 M.D. per small lightning bolt. While it is used as a protective force it does 3D6 S.D.C. and cannot fire', 1, 'Close combat as a blunt weapon; 1200 feet (366 m) for bolts', '10 P.P.E. or 15 I.S.P. to activate; one melee round (15 seconds) per level of experience of the one who activates it, as a weapon or as a protective force', 'Four bolts per melee round at most; each bolt counts as one melee attack', NULL, NULL, NULL, 'A 2-3 foot (0.6 to 0.9 m) rod plated in gold or copper with an insulated, sword-like grip. Instead of fighting with it, the wielder can have it absorb energy attacks - M.D. energy blasts, lightning, plasma, fire, lasers - while magic energy, kinetic attacks, explosions and psionics still do full damage. +2 to strike with bolts, +1 to strike in melee. To create: Call Lightning (15) and 150 P.P.E. From the Rifts RPG.', 'Rifts Book of Magic p.320', NULL),
  ('tw-lightning-spear', 'Lightning Spear', 'rifts', 'weapon', NULL, 75000, '75,000-100,000 credits; 300,000-400,000 for one that returns to its thrower, which also costs an additional 15 P.P.E. or 30 I.S.P. to activate. The standard spear is reasonably common with fair availability; those that return are rare.', '2D6+3 M.D. as a stabbing weapon; 1D6 M.D. from the blunt end; 1D6x10 M.D. on impact when thrown', 1, 'Hand to hand, or 2000 feet (610 m) when thrown', '13 P.P.E. or 24 I.S.P. to activate; one melee round (15 seconds) per level of experience of the one who activates it', NULL, NULL, NULL, NULL, 'A 4-7 foot (1.2 to 2.1 m) rod plated in gold or copper whose spearhead crackles with electricity when activated. +2 to strike when thrown, +1 to strike and parry in hand to hand. To create: Call Lightning (15), Fly (15) and 123 P.P.E.; the returning version also needs Teleport: Lesser. New in this book.', 'Rifts Book of Magic p.320', NULL),
  ('tw-lightning-staff', 'Lightning Staff (Storm Staff)', 'rifts', 'weapon', NULL, 125000, '125,000-225,000 credits. Rare.', '6D6 M.D. per lightning bolt; 2D6 M.D. as a blunt weapon', 1, 'Bolt: 1000 feet (305 m), or close combat', '30 P.P.E. or 60 I.S.P. to recharge; one melee round (15 seconds) per level of the user', 'Up to four lightning bolts per melee', NULL, NULL, 50, 'An enchanted wooden staff capped in copper or silver with a lightning-bolt ornament. While energized it makes the wielder alone invulnerable to energy attacks and can still throw bolts; magic energy, kinetic attacks, explosions and psionics do full damage. It can parry hand to hand attacks from supernaturally strong creatures. +2 to strike with a bolt, +1 to strike and parry in hand to hand. To create: 500 P.P.E. and the spells Call Lightning (15), Lightning Arc (30) and Ironwood (50); 6D6+10 hours.', 'Rifts Book of Magic p.320', NULL),
  ('tw-mirrorshield', 'Mirrorshield', 'rifts', 'weapon', NULL, 220000, '220,000-440,000 credits; poor availability.', 'Varies with the attack deflected; 2D4 M.D. on a physical strike while energized, 3D6 S.D.C. otherwise', 1, 'Deflected energy blasts: 500 feet (152 m)', '20 P.P.E. or 40 I.S.P. to activate; two minutes (8 melee rounds)', NULL, NULL, NULL, 40, 'A highly polished, silver-plated shield that parries hand to hand attacks as usual and sends energy attacks back at the shooter. It has 40 M.D.C.; with the deflection active it gains another 60 and takes one quarter damage. +3 to parry physical attacks; the penalty to parry energy blasts is halved (-5 on an unmodified roll), and a parried blast returns at the shooter. To create: 250 P.P.E. and the spells Magic Shield (6), Deflect (10), Targeted Deflection (15) and Power Weapon (35); 8D6+6 hours.', 'Rifts Book of Magic p.320-321', NULL),
  ('nuhr-tw-kisentite-bayonet', 'Nuhr TW Kisentite Bayonet', 'rifts', 'weapon', 1.6, 2000, '2,000 credits. Generally available only to residents and allies of Queenston Harbor.', '2D6 M.D.; a Supernatural P.S. adds its punch damage', 1, 'Melee', NULL, NULL, 16, NULL, 500, 'A bayonet or long knife of Kisentite, an ultra-dense metal from another dimension, issued to the regular troops of Queenston Harbor; it fits a musket muzzle or serves as a dagger. +1 to strike and +2 to parry. It can be harmed only by a called shot at -1 to hit (-5 for guns and projectile weapons).', 'Rifts Book of Magic p.321', NULL),
  ('nuhr-tw-kisentite-sword', 'Nuhr TW Kisentite Sword', 'rifts', 'weapon', 5, 4500, '4,500 credits. Generally available only to residents and allies of Queenston Harbor.', '2D6+4 M.D.; a Supernatural P.S. adds its punch damage', 1, 'Melee', NULL, NULL, 16, NULL, 500, 'The short, curved Kisentite sword issued to officers of Queenston Harbor. +1 to strike and +2 to parry. It can be harmed only by a called shot at -1 to hit (-5 for guns and projectile weapons).', 'Rifts Book of Magic p.321', NULL),
  ('tw-sawstaff', 'TW Sawstaff', 'rifts', 'weapon', NULL, 110000, '110,000 credits. Fair availability.', '3D6+2 M.D. per strike', 1, 'Melee', '15 P.P.E. or 30 I.S.P. to activate; six minutes (24 melees) per activation', NULL, NULL, NULL, NULL, 'A pole-arm with a long serrated saw blade at its head that spins as if motorized. Its loud buzz rules out stealth and gives a Horror Factor of 10 to any enemy within 10 feet (3 m); the first wound it deals calls for a save against a Horror Factor of 12. +1 to strike and +2 to parry. The entry''s opening line says 10 P.P.E. revs the blade, while its stat line prints 15. To create: an M.D.C. shaft with two handles, a buzz saw and motor, a pink or clear crystal, and the spells Horror (10), Spinning Blades (20), Thunder Clap (4) and Energy Bolt (6).', 'Rifts Book of Magic p.321', NULL),
  ('tw-spin-disk-shooter-crossbow', 'Spin-Disk Shooter (Crossbow)', 'rifts', 'weapon', NULL, 65000, '65,000 credits for the crossbow-style gun. Fair availability.', '3D6 M.D. per charged disk; uncharged, 3D6 S.D.C./Hit Points (a silver-edged blade does 6D6 to the undead and others vulnerable to silver)', 1, '700 feet (213 m)', 'One disk at a time, reloaded by hand. 5 P.P.E. charges a disk, which holds the charge 15 minutes per level of the user', 'As W.P. Archery if known; otherwise each shot and each reload counts as a melee attack', NULL, NULL, 25, 'A crossbow-like launcher for spin-disks, toothed blades about the size of a paper plate that fly as Mega-Damage buzz saws and are loud once launched. A disk is an ordinary S.D.C. weapon again after it hits. +1 to strike. 143 P.P.E. to create any type of shooter.', 'Rifts Book of Magic p.321-322', NULL),
  ('tw-spin-disk-shooter-forearm-launcher', 'Spin-Disk Shooter (Forearm Launcher)', 'rifts', 'weapon', NULL, 95000, '95,000 credits for one forearm launcher. Fair availability.', '3D6 M.D. per charged disk; a pair fired together does 6D6 M.D. to one target or 3D6 M.D. to each of two (no strike bonuses at two targets). Uncharged, 3D6 S.D.C./Hit Points (a silver-edged blade does 6D6 to the undead and others vulnerable to silver)', 1, '400 feet (122 m)', 'One disk at a time, reloaded by hand. 5 P.P.E. charges a disk, which holds the charge 15 minutes per level of the user', 'As W.P. Archery if known; otherwise each shot and each reload counts as a melee attack', NULL, NULL, 12, 'The spin-disk launcher built as a vambrace that fastens to the arm or armor; one on each forearm can be used as paired weapons. A disk is an ordinary S.D.C. weapon again after it hits. +1 to strike. 143 P.P.E. to create any type of shooter.', 'Rifts Book of Magic p.321-322', NULL),
  ('tw-chainsaw', 'Techno-Wizard Chainsaw', 'rifts', 'weapon', NULL, 160000, '160,000 credits; fair to good availability.', '1D4x10 M.D. per strike', 1, 'Melee', '20 P.P.E. or 40 I.S.P. to activate; three minutes (12 melee rounds)', NULL, NULL, NULL, NULL, 'A heavy, magic-powered chainsaw modeled on the Juicer Chainsaw, better as a tool for cutting Mega-Damage chains, doors and fortifications than as a weapon. A user with a P.S. below 30 is -4 to strike and -6 to parry, and any missed roll to hit has a 01-25% chance of hitting the user or something nearby. Horror Factor 12 when activated.', 'Rifts Book of Magic p.322', NULL),
  ('tw-throwing-irons', 'TW Throwing Irons', 'rifts', 'weapon', NULL, 25000, '25,000 credits each. Fair to good availability.', '1D6 M.D. each for shuriken to saucer plate-sized disks; 2D4 for large disks; 2D6 M.D. for African or boomerang-style throwing irons. Silver ones do double damage to creatures vulnerable to silver', 1, '200 feet (61 m)', '2 P.P.E. to activate; an ordinary S.D.C. weapon again after it is thrown and hits, and it can be recharged', 'Equal to the number of hand to hand attacks per melee; two shuriken-sized irons can be thrown at once one-handed', NULL, NULL, NULL, 'Throwing disks and blades with a small clear or light blue crystal at the center or hilt, nearly silent in flight. One in each hand counts as a single melee attack only with Paired Weapons or Targeting; two thrown at one target take one roll, and at two targets no strike bonuses apply.', 'Rifts Book of Magic p.322', NULL),
  ('tw-laser-pistol', 'TW Laser Pistol', 'rifts', 'weapon', NULL, 50000, 'Gun: 50,000 credits. Stormspire versions cost 90,000 with a P.P.E. clip.', '2D6 M.D. per blast', 1, '800 feet (244 m)', '10 shots (7 P.P.E. to reload completely); the Stormspire version with a P.P.E. clip has 24 shots', 'Single shot; each blast counts as one melee attack', NULL, NULL, NULL, 'The standard Techno-Wizard laser pistol, listed with condensed stats among the TW pistols and revolvers.', 'Rifts Book of Magic p.323', NULL),
  ('tw-nuhr-firebolt-musket', 'TW Nuhr Firebolt Musket', 'rifts', 'weapon', 10, 52000, 'Market cost: 52,000 credits.', '6D6 M.D.', 1, '1600 feet (488 m)', '50 shots; any practitioner of magic recharges it for 40 P.P.E.', 'Aimed shots only', NULL, NULL, NULL, 'A Techno-Wizard weapon shaped like an 18th century flintlock musket, the standard arm of the enlisted Queenston Harbor Guard. Anyone can fire it, but only men of magic or a pyramid can recharge its internal cell. +1 to strike. Several thousand have been sold to pirates, mercenaries, adventurers and the Lazlo Militia.', 'Rifts Book of Magic p.323', NULL),
  ('tw-nuhr-firebolt-pistol', 'TW Nuhr Firebolt Pistol', 'rifts', 'weapon', 4, 25000, 'Market cost: 25,000 credits.', '4D6 M.D.', 1, '800 feet (244 m)', '35 shots; any practitioner of magic recharges it for 25 P.P.E.', 'Aimed shots only', NULL, NULL, NULL, 'The flintlock-styled pistol version of the Firebolt Musket, with less range and accuracy; Queenston Harbor Guard officers carry a brace of two. Anyone can fire it, but only men of magic or a pyramid can recharge its internal cell.', 'Rifts Book of Magic p.323', NULL),
  ('tw-plasma-rifle', 'TW Plasma Rifle', 'rifts', 'weapon', NULL, 80000, 'Standard rifle: 80,000 credits. Stormspire gun: 95,000 credits plus 40,000 for the P.P.E. clip.', '4D6 M.D. per bolt (1D4x10 at ley lines)', 1, '1500 feet (457.2 m)', '10 shots for a standard weapon, 15 for a Stormspire weapon with a P.P.E. clip. The Tolkeen and most other versions use no clip and take 12 P.P.E. (or 24 I.S.P.) to recharge five blasts', 'Single shot; each counts as one melee attack', NULL, NULL, NULL, 'A large, heavy weapon that fires bolts of Mega-Damage fire, favored by heavy infantry, Brodkil, Gargoyles and strong D-Bees. Listed under TW Heavy Weapons; not the Splugorth plasma rifle.', 'Rifts Book of Magic p.327', NULL),
  ('tw-rocket-staff', 'Rocket Staff', 'rifts', 'weapon', NULL, 65000, '65,000 credits for the staff; 10,000 credits for each mini-rocket and 30,000 for one large rocket.', 'Large rocket: 2D4x10 M.D. to everything in a 30 foot (9.1 m) radius. Mini-rockets: 4D6 M.D. per rocket fired', 1, 'Large rocket: up to three miles (4.8 km). Mini-rockets: up to 4000 feet (1219 m)', 'One large rocket or 2-6 small rockets; 4 P.P.E. to activate and launch each', 'Mini-rockets can be fired in volleys', NULL, NULL, NULL, 'A plain pole with a rocket, or several small ones, mounted at the top. The user pulls a pin, pumps in the P.P.E. and sends each rocket to a target he can see (optics may be used for distant ones). 140 P.P.E. to create the staff.', 'Rifts Book of Magic p.327', NULL),
  ('tw-shard-rifle', 'TW Shard Rifle', 'rifts', 'weapon', NULL, 140000, '140,000 credits for the rifle; 40,000 credits for each P.P.E. clip.', '2D6+1 M.D. per single shot; 4D6 M.D. per short burst; 6D6 M.D. per long burst; 1D6x10 M.D. per entire magazine burst', 1, '1,200 feet (366 m)', '24 shots per P.P.E. clip', 'Single shot or burst: a short burst fires 5 shots, a long burst 13, a full melee burst 24', NULL, NULL, NULL, 'An automatic upgrade of the TW Shard Pistol that fires magically made ice fragments; light and reliable, though short on range.', 'Rifts Book of Magic p.327', NULL),
  ('tw-starfire-rifle', 'TW Starfire Rifle', 'rifts', 'weapon', NULL, 225000, 'Tolkeen version: 250,000 credits. Stormspire version: 225,000 credits for the rifle and 40,000 per P.P.E. clip.', '6D6+6 M.D. per shot (1D6x10+6 at ley lines)', 1, '1,500 feet (457.2 m)', '6 shots per P.P.E. clip; the Stormspire version holds two clips (12 shots). The Tolkeen version uses no clip and takes 20 P.P.E. (or 40 I.S.P.) to recharge three blasts', 'Single shots only; each counts as one melee attack', NULL, NULL, NULL, 'A heavy Techno-Wizard energy rifle listed under TW Heavy Weapons. +1 to strike.', 'Rifts Book of Magic p.327', NULL),
  ('tw-tk-80-heavy-machine-gun', 'TK-80 Heavy Machine-gun', 'rifts', 'weapon', NULL, 160000, 'The entry prints two cost lines. The first: 500,000 credits for the machine-gun and 100,000 for each P.P.E. power pack. The last: 160,000 for the standard TK-80; Stormspire version 140,000 credits plus 40,000 for each P.P.E. clip. The last line''s standard figure is the one stored.', '2D4 M.D. per single shot; 3D6 per short burst; 5D6 per long burst; 2D6x10 M.D. from a full melee burst of 50 shots', 1, '4000 feet (1219 m); double at ley lines. -3 to strike beyond 3,000 feet (914 m) without a spotter or enhanced vision', '200 TK rounds standard (Tolkeen and most makers); the Stormspire version adds two P.P.E. clips for 260. Every version recharges at one P.P.E. (or 2 I.S.P.) per TK round', 'Burst firing only: a short burst fires 5 shots, a long burst 10, a full melee burst 50', NULL, NULL, NULL, 'A telekinetic heavy machine-gun with rail gun-like fire power, usually vehicle-mounted or fired from a bipod or tripod; Brodkil use it as a two-handed rifle. A character with a P.S. under 24 is -4 to strike even with both hands. +1 to strike.', 'Rifts Book of Magic p.327', NULL),
  ('tw-firedemon-flamethrower', 'Firedemon Flamethrower', 'rifts', 'weapon', NULL, 450000, '450,000 credits for the flamethrower. Fair availability.', '5D6 M.D. per single blast (one target) per melee round; a living target must save vs Horror Factor 14 or lose one attack and initiative and be -4 to dodge', 1, '1000 feet (305 m)', '10 blasts. 50 P.P.E. or 100 I.S.P. recharges two blasts, so 250 P.P.E. or 500 I.S.P. reloads it fully', NULL, NULL, NULL, NULL, 'A heavy TW flamethrower whose burst of clinging fire takes the shape of a wailing, clawed banshee; popular in the New West and Stormspire. To create: a ruby worth 2000 credits, a flamethrower with a gold-plated nozzle, 350 P.P.E., and the spells Fire Globe (40), Fire Ball (10), Fuel Flame (5), Fly as the Eagle (25), Horror (10) and Horrific Illusion (10); 1D4 days.', 'Rifts Book of Magic p.328', NULL),
  ('tw-firedemon-revolver', 'Firedemon Revolver', 'rifts', 'weapon', NULL, 300000, '300,000-350,000 credits for the revolver. Fair availability.', '5D6 M.D. per single blast (one target) per melee round; a living target must save vs Horror Factor 14 or lose one attack and initiative and be -4 to dodge', 1, '1000 feet (305 m)', 'Two blasts. 50 P.P.E. or 100 I.S.P. recharges both', NULL, NULL, NULL, NULL, 'The Firedemon magic built into a gold-plated revolver instead of a flamethrower. To create: a ruby worth 2000 credits, the revolver, 250 P.P.E., and the spells Fire Globe (40), Fire Ball (10), Fuel Flame (5), Fly as the Eagle (25), Horror (10) and Horrific Illusion (10); 1D4 days.', 'Rifts Book of Magic p.328', NULL),
  ('tw-flare-animal-repellent', 'TW Flare: Animal Repellent', 'rifts', 'gear', NULL, 6000, '6,000 credits per flare.', NULL, 0, 'An area of about five feet (1.5 m)', 'One use; 1D4 minutes', NULL, NULL, NULL, NULL, 'A hand-held flare lit by a pull cord. It fires nothing: it gives off a mint scent and a magic aura that repels up to six large animals such as wolves and 20 small ones such as rats, mice and bats. Several can be scattered to widen the area; moving a flare makes it burn out twice as fast.', 'Rifts Book of Magic p.328', NULL),
  ('tw-flare-globe-of-daylight', 'TW Flare: Globe of Daylight', 'rifts', 'gear', NULL, 2000, '2,000 credits per flare.', NULL, 0, 'Bursts 200 feet (61 m) in the air, then hovers about 20 feet (6.1 m) above the ground', 'One use; 3D4 minutes', NULL, NULL, NULL, NULL, 'A flare fired from a flare gun or launched like a rocket that releases a stationary magic globe of daylight, holding vampires at the edge of its light as the spell does. Shot into a vampire it does no damage, but still bursts into light. Also a signal flare.', 'Rifts Book of Magic p.328', NULL),
  ('tw-flare-storm', 'TW Flare: Storm', 'rifts', 'weapon', NULL, 10000, '10,000 credits per flare.', '4D6x10 Hit Points to a vampire for every half melee round (7.5 seconds) in the rain', 0, 'Bursts 2000 feet (610 m) in the air; the storm covers a 100 foot (30.5 m) circle', 'One use; the storm lasts 1D6 minutes', NULL, NULL, NULL, NULL, 'A flare fired from a flare gun or launched like a rocket that brings on a sudden, small rainstorm. Shot into a vampire it does no damage and makes no storm.', 'Rifts Book of Magic p.328', NULL),
  ('tw-goblin-bomb-blinding-flash', 'Goblin Bomb: Blinding Flash', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', NULL, 0, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'Momentarily blinds an opponent; best indoors and in the dark. The Goblin wears sunglasses. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.328-329', NULL);

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('tw-goblin-bomb-carpet-of-adhesion', 'Goblin Bomb: Carpet of Adhesion', 'rifts', 'weapon', NULL, 16000, 'Usually 16,000 credits: 4,000 per level of the spell evoked, and this is a fourth level invocation.', NULL, 0, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'Whoever or whatever it strikes is stuck to a Carpet of Adhesion for up to 30 melee rounds, or 2D6 rounds on a successful save vs magic. The Goblin''s face drips with goo. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.328-329', NULL),
  ('tw-goblin-bomb-extinguish-fire', 'Goblin Bomb: Extinguish Fire', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', NULL, 0, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'Instantly puts out all fire within a 20 foot (6 m) radius of where it lands. The Goblin is smiling. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.329', NULL),
  ('tw-goblin-bomb-fear', 'Goblin Bomb: Fear Grenade', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', NULL, 0, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'Creates an aura of fear over everybody within a 20 foot (6 m) radius of where it lands. The Goblin is screaming. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.329', NULL),
  ('tw-goblin-bomb-fire-bomb', 'Goblin Bomb: Fire Bomb', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', '4D6 M.D. by fire to a six foot (1.8 m) diameter', 1, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'A fire burst drawn on the Fire Bolt spell. Combustibles have a 01-80% likelihood of catching S.D.C. flame; otherwise the flames die in four seconds. The Goblin has fire for hair. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.329', NULL),
  ('tw-goblin-bomb-fuel-flame', 'Goblin Bomb: Fuel Flame', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', NULL, 0, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'Doubles the size of any fire, affecting up to a 10 foot (3 m) diameter. The Goblin breathes fire. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.329', NULL),
  ('tw-goblin-bomb-lightning-bomb', 'Goblin Bomb: Lightning Bomb', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', '2D6+2 M.D. to everybody in a three foot (0.9 m) radius', 1, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'An electrical blast based on Electric Arc; it usually catches one person, three or four if they are clustered. The Goblin''s hair stands on end. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.329', NULL),
  ('tw-goblin-bomb-orb-of-cold', 'Goblin Bomb: Orb of Cold', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', '3D6 M.D. plus cold penalties to a three foot (0.9 m) radius', 1, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'A burst of cold that usually catches one person, three or four if they are clustered. The Goblin has icicles on its eyebrows and nose. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.329', NULL),
  ('tw-goblin-bomb-smoke', 'Goblin Bomb: Smoke', 'rifts', 'weapon', NULL, NULL, 'Generally 4,000 credits per level of the spell evoked; the book prints no figure for this bomb.', NULL, 0, 'Thrown up to 100 feet (30.5 m) by humans, double with a P.S. of 20 or greater, triple with Supernatural P.S.; up to 1200 feet (366 m) from a catapult. As an arrow warhead the bow''s range is halved', 'Single use. Pull the pin and pump in 2 P.P.E. (or 4 I.S.P.); it detonates five seconds later', NULL, NULL, NULL, NULL, 'Makes a 30x30x30 foot (9.1 m) cloud of smoke that lasts 45 seconds (3 melee rounds), for cover and distraction. The Goblin purses its lips to blow smoke rings. A Goblin Bomb is a softball-sized TW grenade with a Goblin''s face that looses its spell at roughly 3rd level strength; 130 P.P.E. to create plus the spell''s own cost.', 'Rifts Book of Magic p.329', NULL),
  ('tw-paralysis-grenade', 'TW Paralysis Grenade', 'rifts', 'weapon', 0.5, 8000, '8,000 to 10,000 credits per grenade. Fair availability.', NULL, 0, 'Thrown 60-100 feet (18.3 to 30.5 m); affects 1D4+2 mortal beings within a 10 foot (3 m) diameter', 'One charge at a time; 12 P.P.E. or 24 I.S.P. to recharge, and the canister can be reused up to 10 times', NULL, NULL, NULL, NULL, 'A canister that goes off on impact and, rather than exploding, gives off an unseen field equal to Paralysis: Lesser: a random limb of each victim (percentile roll: right arm, left arm or tail, right leg, left leg or wing) is paralyzed for 4 minutes (16 melee rounds) unless he saves vs magic at 12 or higher. Radius and duration double on ley lines and at nexus points. To create: a cardboard tube or canister, a cube-cut crystal worth 100 credits, a pull ring, Energy Bolt (5), Paralysis: Lesser (5) and 60 P.P.E. in all; 1D6 hours.', 'Rifts Book of Magic p.329', NULL),
  ('tw-vampire-chaser-steam-grenade', '"Vampire Chaser" Steam Grenade', 'rifts', 'weapon', NULL, 2000, '2,000-4,000 credits; only 1000 along the border of Mexico, where they are most common. Fair to good availability throughout North America.', '2D6 S.D.C. per melee round to ordinary mortals; 6D6 Hit Points per melee round to vampires', 0, 'Thrown, 100 feet (30.5 m); the steam cloud has a 10 foot (3 m) radius', 'The cloud lasts one minute (4 melee rounds). Reusable: 25 P.P.E. or 50 I.S.P. recharges it, at least 60 times before it burns out', NULL, NULL, NULL, NULL, 'A round, usually blue grenade with a small aquamarine trigger, designed at Arzno Weapons Manufacturing and copied by the Colorado Baronies. Its hot steam burns bare skin and blinds (-10 to strike, parry and dodge) inside the cloud and for 1D6 melee rounds after, and drives vampires out of hiding. Once made, anybody can use it. To create: 60 P.P.E., an aquamarine (40 credits), a conventional grenade, and the spells Create Water (15), Ignite Fire (6) and Fuel Flame (5).', 'Rifts Book of Magic p.329', NULL),
  ('tw-plastic-water-pistol', 'TW Plastic Water Pistol', 'rifts', 'weapon', NULL, 6000, '6,000 credits.', '2D6 Hit Points to vampires', 0, '150 feet (46 m)', '40 blasts; 10 P.P.E. or 20 I.S.P. to recharge', 'Each water blast generally counts as one melee attack', NULL, NULL, NULL, 'A squirt-gun water blaster for fighting vampires. A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-metal-water-pistol', 'TW Metal Water Pistol', 'rifts', 'weapon', NULL, 10000, '10,000 credits.', '2D6 Hit Points to vampires', 0, '200 feet (61 m)', '40 blasts; 10 P.P.E. or 20 I.S.P. to recharge', 'Each water blast generally counts as one melee attack', NULL, NULL, NULL, 'A metal water pistol for fighting vampires. A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-pump-style-water-pistol', 'TW Pump Style Water Pistol or Sawed-Off Shotgun', 'rifts', 'weapon', NULL, 20000, '20,000 credits.', '4D6 Hit Points to vampires', 0, '200 feet (61 m)', '40 blasts; 10 P.P.E. or 20 I.S.P. to recharge', 'Each water blast generally counts as one melee attack', NULL, NULL, NULL, 'A pump-style water blaster that throws a wider, more concentrated blast. A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-full-size-water-shotgun', 'TW Full Size Water Shotgun', 'rifts', 'weapon', NULL, 25000, '25,000 credits.', '5D6 Hit Points to vampires', 0, '300 feet (91 m)', '40 blasts; 10 P.P.E. or 20 I.S.P. to recharge', 'Each water blast generally counts as one melee attack', NULL, NULL, NULL, 'A full-size shotgun-style water blaster. A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-full-size-water-rifle', 'TW Full Size Water Rifle', 'rifts', 'weapon', NULL, 40000, '40,000 credits.', '4D6 Hit Points to vampires', 0, '600 feet (182 m)', '40 blasts; 10 P.P.E. or 20 I.S.P. to recharge', 'Each water blast generally counts as one melee attack', NULL, NULL, NULL, 'A full-size rifle-style water blaster. A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-rifle-and-water-grenade-launcher', 'TW Rifle and Water Grenade Launcher', 'rifts', 'weapon', NULL, 60000, '60,000 credits.', 'Rifle blast: 4D6 Hit Points to vampires. Water grenade: 1D4x10 Hit Points to a 10 foot (3 m) area', 0, '600 feet (182 m)', '20 blasts; each grenade counts as two rifle blasts', 'The grenade can be fired only two times per melee', NULL, NULL, NULL, 'A water rifle with a launcher for balls of water (about 15 gallons) that burst on impact. The grenades are not made to be thrown by hand. A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-water-cannon-bazooka', 'TW Water Cannon Bazooka', 'rifts', 'weapon', NULL, 70000, '70,000 credits.', '2D4x10 Hit Points to vampires', 0, '600 feet (182 m)', '20 blasts', 'Three times per melee at most', NULL, NULL, NULL, 'Fires a ball of water (about 30 gallons) that bursts over a 10 foot (3 m) area. A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-water-cannon', 'TW Water Cannon', 'rifts', 'weapon', NULL, 150000, '150,000 credits.', '3D6x10 Hit Points to vampires', 0, '300 feet (91 m)', '20 blasts', 'Six times per melee at most', NULL, NULL, NULL, 'Looks like a two-handed flame thrower with a hose and a small one gallon tank; it throws a high-pressure stream the full range, soaking a 10 foot (3 m) impact area (about 50 gallons). A Techno-Wizard water blaster needs no reservoir: the water appears as it fires, once 10 P.P.E. or 20 I.S.P. has been pumped in.', 'Rifts Book of Magic p.330', NULL),
  ('tw-vampire-water-field', 'TW Vampire Water Field', 'rifts', 'gear', 5, 50000, '50,000 credits.', '3D6 H.P. to a vampire each time he steps into the water', 0, '2 feet (0.6 m) around the wearer', '10 P.P.E. or 20 I.S.P. to activate; five minutes', NULL, NULL, NULL, NULL, 'A compact backpack that sprouts an umbrella-like tube frame and sprays water all round the wearer (who gets wet too), keeping vampires off. Nicknamed the portable shower.', 'Rifts Book of Magic p.330', NULL),
  ('tw-modified-wood-firing-rail-gun', 'TW Modified Wood Firing Rail Gun', 'rifts', 'weapon', NULL, 500000, '500,000 credits; very rare, but becoming more common.', 'A burst does 1D4 M.D., or 3D6x10 H.P. to vampires', 1, '4000 feet (1219 m)', '40 bursts per every 20 P.P.E. or 40 I.S.P.', NULL, NULL, NULL, NULL, 'Any rail gun magically converted to fire wood shards that appear as it fires, with no ammunition drum; lighter models are preferred. It can no longer fire normal rail gun rounds.', 'Rifts Book of Magic p.330', NULL),
  ('tw-vampire-killer-tww-2000', 'Vampire-Killer TWW-2000', 'rifts', 'weapon', 30, 200000, '200,000 credits. Excellent availability at Arzno, Arizona; fair elsewhere along the Mexican border. Grenades for the launcher are sold separately. Outlawed by the Vampire Kingdoms.', 'Silver-bladed chain saw: 1D6x10 S.D.C., or 5D6 Hit Points to vampires. Cross spotlight: 3D6 Hit Points to vampires. Grenade launcher: wood fragmentation 2D6 M.D., or 8D6 Hit Points to vampires, with a 01-05% chance of hitting the heart of any vampire in the 10 foot (3 m) blast', 0, 'Chain saw: arm length +2 feet. Spotlight: 100 feet (30.5 m). Grenade launcher: 200 feet (61 m)', 'Chain saw: 5 P.P.E. or 10 I.S.P. for five melee rounds; most take an E-Clip for ten hours. Spotlight: battery, effectively unlimited. Launcher: 5 grenades per clip', NULL, NULL, NULL, NULL, 'The Arzno TWW-2000 vampire hunter''s kit: a silver-bladed TW chain saw, a cross spotlight (hand-held or mounted), a grenade launcher (on the saw or separate) that also takes water grenades, TW steam grenades, storm flares and conventional grenades, and basic gear - a 12 inch wooden cross, six wood stakes, a wooden mallet, a pocket mirror, one TW Storm Flare, one Globe of Daylight Flare and two TW Steam Grenades.', 'Rifts Book of Magic p.330', NULL),
  ('tw-water-dagger-tww-1050', 'Water Dagger TWW-1050', 'rifts', 'weapon', NULL, 18000, '18,000 credits; typically twice as much elsewhere in North America.', 'One S.D.C./H.P. point; 2D6 Hit Points to vampires', 0, 'Hand-held; the book prints 2-4 feet (0.6 to 1.2 m) long', '7 P.P.E. or 14 I.S.P. to activate; 10 minutes per activation', NULL, NULL, NULL, NULL, 'A smaller version of the Water Sword: a pipe hilt from which water pours and is held by telekinesis in the shape of a blade. To create: 80 P.P.E., a metal pipe, three aquamarines worth 100 credits each, and the spells Telekinesis and Create Water.', 'Rifts Book of Magic p.330', NULL),
  ('tw-water-sword-tww-1000', 'Water Sword TWW-1000', 'rifts', 'weapon', NULL, 25000, '25,000 credits in the southwest; typically twice as much elsewhere in North America.', '1D4 S.D.C./H.P.; 4D6 Hit Points to vampires', 0, 'Hand held, 2-4 feet (0.6 to 1.2 m) long', '10 P.P.E. or 20 I.S.P. to activate; 10 minutes per activation', NULL, NULL, NULL, NULL, 'An Arzno Weapons Manufacturing weapon: a pipe made into a hilt with three aquamarines round it. Activated, water pours from the handle and is held telekinetically as a blade that stays solid but drenches whatever it hits. To create: 100 P.P.E., a metal pipe, three aquamarines worth 100 credits each, and the spells Telekinesis and Create Water.', 'Rifts Book of Magic p.330-331', NULL),
  ('tw-eyes-of-thoth-reading-glasses', 'Eyes of Thoth Reading Glasses', 'rifts', 'gear', NULL, 8000, '8000 to 20,000 credits; an additional 30% to install in visors, armor helmets and similar optics. Poor availability (new).', NULL, 0, NULL, '10 P.P.E. or 20 I.S.P. to activate; 10 minutes per activation', NULL, NULL, NULL, NULL, 'A pair of frames, lenses optional, with small topaz stones along the earpieces; the wearer can read any language, though not magic wards, circles or symbols. To create: ten small topaz worth about 300 credits in all, an old set of frames, the spells Eyes of Thoth (8) and Energy Bolt (5), and 375 P.P.E.', 'Rifts Book of Magic p.332', NULL),
  ('tw-language-translator', 'TW Language Translator', 'rifts', 'gear', NULL, 15000, '15,000-30,000 credits. Fair to poor availability. Five languages come at the base price; up to another 100 can be added at 160 credits each.', NULL, 0, NULL, '10 P.P.E. or 20 I.S.P. to activate; 10 minutes', NULL, NULL, NULL, NULL, 'A walkie-talkie or small radio transmitter and receiver, each set with a large quartz and three small garnets. Held to the throat, the transmitter renders the user''s speech in another language by the Tongues spell; the receiver, worn at the ear, renders foreign speech in the user''s own, for the languages installed. To create: two large quartz (about 150 credits each), six garnets (50 each), an old radio, the spells Tongues (12) and Energy Bolt (5), and 300 P.P.E.', 'Rifts Book of Magic p.332', NULL),
  ('tw-magic-respirator-and-air-mask', 'Magic Respirator & Air Mask', 'rifts', 'gear', NULL, 13000, '13,000-20,000 credits, easily three times as much on the Black Market. Fair to poor availability.', NULL, 0, NULL, '5 P.P.E. or 10 I.S.P. to activate; 15 minutes', NULL, NULL, NULL, NULL, 'A breath mask or filter with two quartz at the bridge of the nose and an accordion tube at the chin that breathes for a badly injured patient: +40% to save vs coma or death when the trauma is respiratory, and +2 to save against smoke or toxin inhalation. As an air mask it makes the wearer impervious to inhaled toxins, magic smoke, fumes and clouds included. To create: 80 P.P.E., the mask, two clear quartz worth 50 credits each, and the spells Energy Bolt (5), Breathe Without Air (5) and Wind Rush (20).', 'Rifts Book of Magic p.332', NULL),
  ('tw-night-goggles', 'TW Night Goggles', 'rifts', 'gear', NULL, 50000, 'Market value: 50,000 credits.', NULL, 0, 'Vision 120 feet (36.5 m)', '25 P.P.E. or 50 I.S.P. to activate; 15 minutes', NULL, NULL, NULL, NULL, 'Magic goggles that let the wearer see in the dark and see the invisible. 140 P.P.E. to create, with a modified Eyes of the Wolf spell.', 'Rifts Book of Magic p.332', NULL),
  ('tw-scuba-wet-suit-and-diving-gear', 'TW SCUBA Wet Suit and Diving Gear', 'rifts', 'gear', NULL, 10000, 'Market value: 10,000 credits.', NULL, 0, NULL, '5 P.P.E. to activate; 20 minutes, refilled at once by another 5 P.P.E. or 10 I.S.P.', NULL, NULL, NULL, NULL, 'A wet suit with a breathe-without-air respirator and small tank worn in place of normal air tanks and hose. It also works against toxic fumes and in an airless environment. 200 P.P.E. to create, plus the Breathe Without Air spell.', 'Rifts Book of Magic p.332-333', NULL),
  ('tw-super-swimmer-divers-suit', 'Super Swimmer Diver''s Suit', 'rifts', 'gear', NULL, 50000, 'Market value: 50,000 credits.', NULL, 0, NULL, '11 P.P.E. or 22 I.S.P. to activate; 15 minutes', NULL, NULL, NULL, NULL, 'An air mask and skin-diver''s wet suit with a contraption in the belt that gives the powers of Swim As A Fish and Breathe Without Air. 600 P.P.E. to create.', 'Rifts Book of Magic p.333', NULL),
  ('tw-thieves-gloves', 'Thieves'' Gloves', 'rifts', 'gear', NULL, 250000, 'Market value: 250,000 credits. Their sale is prohibited in many towns.', NULL, 0, NULL, '16 P.P.E. or 32 I.S.P. to activate; 15 minutes', NULL, NULL, NULL, NULL, 'Leather gloves with a metal plate over the knuckles, wires along the finger seams and crystal studs, which give the wearer the powers of magic concealment (palming) and escape. 200 P.P.E. to create, plus the Concealment and Escape spells.', 'Rifts Book of Magic p.333', NULL);

